-- RaththamTN: Tamil Nadu Blood Donor Network (PostgreSQL)
-- Run in pgAdmin: right-click "lifelink" > Query Tool > paste > F5

DROP TABLE IF EXISTS donation, request, patient, stock, donor, hospital, admin CASCADE;

CREATE TABLE donor(
  donor_id SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  age INT CHECK (age BETWEEN 18 AND 65),
  gender VARCHAR(10),
  blood_group VARCHAR(10) NOT NULL CHECK (blood_group IN ('A+','A-','B+','B-','AB+','AB-','O+','O-',
    'A1+','A1-','A2+','A2-','A1B+','A1B-','A2B+','A2B-','Bombay')),
  phone VARCHAR(15) NOT NULL,
  district VARCHAR(60) NOT NULL,
  last_donation_date DATE,
  total_donations INT DEFAULT 0);

CREATE TABLE hospital(
  hospital_id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  district VARCHAR(60) NOT NULL,
  phone VARCHAR(20));

CREATE TABLE stock(
  hospital_id INT REFERENCES hospital(hospital_id),
  blood_group VARCHAR(10),
  units INT DEFAULT 0 CHECK (units >= 0),
  PRIMARY KEY (hospital_id, blood_group));

CREATE TABLE patient(
  patient_id SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  age INT,
  blood_group VARCHAR(10) NOT NULL,
  hospital_id INT REFERENCES hospital(hospital_id),
  district VARCHAR(60) NOT NULL,
  phone VARCHAR(15) NOT NULL);

CREATE TABLE request(
  request_id SERIAL PRIMARY KEY,
  patient_id INT REFERENCES patient(patient_id),
  urgency VARCHAR(10) CHECK (urgency IN ('Normal','Urgent','Emergency')),
  request_date DATE DEFAULT CURRENT_DATE,
  status VARCHAR(15) DEFAULT 'Pending');

CREATE TABLE donation(
  donation_id SERIAL PRIMARY KEY,
  donor_id INT REFERENCES donor(donor_id),
  request_id INT REFERENCES request(request_id),
  hospital_id INT REFERENCES hospital(hospital_id),
  donation_date DATE DEFAULT CURRENT_DATE,
  units INT DEFAULT 1);

CREATE TABLE admin(
  admin_id SERIAL PRIMARY KEY,
  username VARCHAR(50) UNIQUE NOT NULL,
  password VARCHAR(100) NOT NULL);

-- VIEW: donors who can donate today (90-day gap)
CREATE VIEW available_donors AS
  SELECT * FROM donor
  WHERE last_donation_date IS NULL OR last_donation_date <= CURRENT_DATE - 90;

-- TRIGGER: after a donation, update donor's last date + count and hospital stock
CREATE OR REPLACE FUNCTION after_donation_fn() RETURNS TRIGGER AS $$
DECLARE bg VARCHAR(10);
BEGIN
  SELECT blood_group INTO bg FROM donor WHERE donor_id = NEW.donor_id;
  UPDATE donor SET last_donation_date = NEW.donation_date, total_donations = total_donations + 1
    WHERE donor_id = NEW.donor_id;
    ON CONFLICT (hospital_id, blood_group) DO UPDATE SET units = stock.units + NEW.units;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER after_donation AFTER INSERT ON donation
  FOR EACH ROW EXECUTE FUNCTION after_donation_fn();

